<h1 class="h">Nový doklad</h1><div class="sub">Zadejte minimum. Položky se přepočítají automaticky.</div>
<form class="form" method="post"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="row"><div class="field"><label>Typ dokladu</label><select name="doc_type"><option value="invoice">Faktura</option><option value="offer">Nabídka</option><option value="order">Objednávka</option><option value="proforma">Zálohová faktura</option><option value="credit">Dobropis</option></select></div><div class="field"><label>Zákazník</label><select name="customer_id" required><option value="">Vyberte</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=View::e($c['company_name']?:trim(($c['first_name']??'').' '.($c['last_name']??'')))?></option><?php endforeach;?></select></div></div><div class="row"><div class="field"><label>Datum vystavení</label><input type="date" name="issue_date" value="<?=date('Y-m-d')?>"></div><div class="field"><label>Splatnost</label><input type="date" name="due_date" value="<?=date('Y-m-d',strtotime('+14 days'))?>"></div></div>
<div class="card"><div style="font-weight:800;margin-bottom:12px">Položky</div><div id="items"><?php for($i=0;$i<3;$i++):?><div class="row item" style="margin-bottom:10px"><div class="field"><label>Název</label><input name="item_name[]" placeholder="Např. Konzultace"></div><div class="field"><label>Množství / jednotka</label><div style="display:flex;gap:7px"><input name="item_qty[]" type="number" step="0.01" value="1"><input name="item_unit[]" value="ks"></div></div><div class="field"><label>Jednotková cena</label><input name="item_price[]" type="number" step="0.01" value="0"></div><div class="field"><label>DPH %</label><input name="item_vat[]" type="number" step="0.01" value="21"></div></div><?php endfor;?></div><button type="button" class="btn" onclick="addItem()">+ Položka</button></div>
<button class="btn primary">Vytvořit doklad</button></form>
<script>function addItem(){let x=document.querySelector('.item').cloneNode(true);x.querySelectorAll('input').forEach(i=>{if(i.name.includes('item_qty'))i.value=1;else if(i.name.includes('item_vat'))i.value=21;else if(i.name.includes('item_unit'))i.value='ks';else i.value=''});document.getElementById('items').appendChild(x)}</script>
